const crypto = require('crypto');

const SECRET = 'nexus-dev-secret';
try {
  const rawBody = typeof $json.body === 'string' ? $json.body : JSON.stringify($json.body);
  const headers = $json.headers || {};
  const sig = headers['x-nexus-signature'] || '';
  const expected = crypto.createHmac('sha256', SECRET).update(String(rawBody)).digest('hex');
  let signature_valid = sig.length === expected.length && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));

  let payload = {};
  try { payload = JSON.parse(rawBody); } catch (e) { payload = $json.body || {}; }

  const message = payload.workflow === 'task_reminder'
    ? 'Reminder: task "' + payload.title + '" (' + payload.department + ') is overdue - due ' + payload.due_date
    : 'Document "' + payload.filename + '" approved by human review - task routed to ' + payload.department;

  return { json: { signature_valid, workflow: payload.workflow, message } };
} catch (e) {
  return { json: { signature_valid: false, error: String(e && e.message ? e.message : e) } };
}
